def find_fields(describe, keywords):
    kws=[k.lower() for k in keywords]
    out=[]
    for f in (describe.get('fields',[]) or []):
        s=((f.get('label') or '')+' '+(f.get('name') or '')).lower()
        if any(k in s for k in kws):
            out.append((f.get('label'),f.get('name'),f.get('type')))
    return sorted(out)
